import Dispatch
func findBook(id: Int, done: @escaping (String) -> Void) {
    let index = DispatchQueue(label: "library.index")
    let settings = DispatchQueue(label: "library.settings")
    index.async {
        print("Индекс \(id)")
        settings.async {
            print("Настройки")
            index.async {
                let title = "Книга \(id)"
                DispatchQueue.main.async { done(title) }
            }
        }
    }
}

Для id 41: «Индекс 41», «Настройки», затем callback «Книга 41». Нигде внутри цепочки нет ожидания своей будущей работы.

